using System.Security.Cryptography.X509Certificates;
using Pinball_Aegis.Application.Interfaces;

namespace Pinball_Aegis.Infrastructure.Services;

// Loads the workstation mTLS certificate generated by wp-tools
public class WorkstationCertificateProvider : IWorkstationCertificateProvider
{
    private readonly X509Certificate2? _certificate;

    public bool HasCertificate => _certificate is not null;
    public X509Certificate2? GetCertificate() => _certificate;
    public string? CertificateThumbprint => _certificate?.Thumbprint;

    public WorkstationCertificateProvider(string? customPath = null)
    {
        _certificate = LoadCertificate(customPath);
    }

    private static X509Certificate2? LoadCertificate(string? customPath)
    {
        // Candidate locations where wp-tools may have installed the certificate
        var candidateDirectories = new List<string>();

        if (!string.IsNullOrWhiteSpace(customPath) && Directory.Exists(customPath))
        {
            candidateDirectories.Add(customPath);
        }

        // 1. Current application working directory
        candidateDirectories.Add(AppDomain.CurrentDomain.BaseDirectory);

        // 2. Production shared system path (%ProgramData%\WorldPinball\Aegis)
        candidateDirectories.Add(Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),
            "WorldPinball", "Aegis"));

        // 3. Local dev fallback (the wp-tools folder where we just generated it)
        candidateDirectories.Add(@"D:\Workspace\GoProject\wp-tools");

        foreach (var dir in candidateDirectories)
        {
            var certPath = Path.Combine(dir, "workstation.crt");
            var keyPath = Path.Combine(dir, "workstation.key");

            if (File.Exists(certPath) && File.Exists(keyPath))
            {
                // .NET 10 native PEM loader for ECDSA P-256 certificate + private key
                return X509Certificate2.CreateFromPemFile(certPath, keyPath);
            }
        }

        return null;
    }
}